/// Rust half of the QObject. A single persistent Transport keeps the cookie
/// jar alive across calls, which is what makes QR login work.
pub struct SparkMusicClientRust {
    transport: Transport,
    db: Database,
    /// Envelope and type used to create the current QR key; polling must use
    /// the same pair, otherwise the server sees two different clients and
    /// answers 8821.
    qr_mode: RwLock<String>,
    qr_type: RwLock<i32>,
    /// A webplayer login carries a MUSIC_A anonymous identity; register it
    /// once before the first QR key. Reset by clearCookies.
    anonymous_tried: RwLock<bool>,
}

impl Default for SparkMusicClientRust {
    fn default() -> Self {
        Self {
            transport: Transport::new("eapi", "", &random_alnum(32)),
            db: Database::open_default()
                .unwrap_or_else(|_| Database::open_in_memory().expect("in-memory database")),
            qr_mode: RwLock::new("api".to_string()),
            qr_type: RwLock::new(3),
            anonymous_tried: RwLock::new(false),
        }
    }
}

fn qstring(value: impl AsRef<str>) -> QString {
    QString::from(value.as_ref())
}

fn result_json(result: CoreResult<Value>) -> QString {
    match result {
        Ok(value) => qstring(value.to_string()),
        Err(error) => qstring(error.to_json().to_string()),
    }
}

fn parse_params(json: &str) -> Map<String, Value> {
    match serde_json::from_str::<Value>(json) {
        Ok(Value::Object(map)) => map,
        _ => Map::new(),
    }
}

fn id_value(id: &str) -> Value {
    match id.parse::<u64>() {
        Ok(number) => Value::from(number),
        Err(_) => Value::String(id.to_string()),
    }
}

/// `"347230,347231"` -> `"[347230,347231]"`, the app's JSON-array form.
fn ids_json(ids: &str) -> String {
    let items: Vec<String> = ids
        .split(',')
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(|s| id_value(s).to_string())
        .collect();
    format!("[{}]", items.join(","))
}

fn track_count(value: &Value) -> usize {
    value
        .pointer("/playlist/tracks")
        .and_then(Value::as_array)
        .map(Vec::len)
        .or_else(|| value.get("songs").and_then(Value::as_array).map(Vec::len))
        .unwrap_or(0)
}

/// The API answers `code: 200` for success; a few wrappers omit `code`
/// entirely on otherwise valid payloads.
fn is_code_ok(value: &Value) -> bool {
    match value.get("code") {
        Some(code) => code.as_i64() == Some(200),
        None => true,
    }
}

/// `playlist.trackIds` entries are objects (`{"id": …}`) in v6 responses, but
/// tolerate bare numbers/strings as well.
fn playlist_track_ids(value: &Value) -> Vec<i64> {
    let Some(ids) = value
        .pointer("/playlist/trackIds")
        .and_then(Value::as_array)
    else {
        return Vec::new();
    };
    ids.iter()
        .filter_map(|item| match item {
            Value::Number(number) => number.as_i64(),
            Value::String(text) => text.parse().ok(),
            Value::Object(object) => object.get("id").and_then(|id| match id {
                Value::Number(number) => number.as_i64(),
                Value::String(text) => text.parse().ok(),
                _ => None,
            }),
            _ => None,
        })
        .collect()
}

/// Only successful playlists with tracks are worth caching. A logged-out or
/// risk-controlled empty answer must not hide later account data for six
/// hours.
fn playlist_cacheable(value: &Value) -> bool {
    is_code_ok(value) && track_count(value) > 0
}

fn default_export_candidates() -> Vec<std::path::PathBuf> {
    let mut out = Vec::new();
    if let Some(dir) = std::env::var_os("XDG_MUSIC_DIR") {
        out.push(std::path::PathBuf::from(dir).join("sparkmusic-favorites.m3u8"));
    }
    if let Some(home) = std::env::var_os("USERPROFILE") {
        out.push(
            std::path::PathBuf::from(home)
                .join("Music")
                .join("sparkmusic-favorites.m3u8"),
        );
    }
    if let Some(home) = std::env::var_os("HOME") {
        out.push(
            std::path::PathBuf::from(home)
                .join("Music")
                .join("sparkmusic-favorites.m3u8"),
        );
    }
    if let Some(data) = crate::db::Database::default_path() {
        if let Some(parent) = data.parent() {
            out.push(parent.join("sparkmusic-favorites.m3u8"));
        }
    }
    out
}

/// The desktop client's anonymous-registration device id is 32 alphanumeric
/// characters. A hex-only id is rejected by `register/anonimous` (code 400),
/// so this is deliberately alphanumeric, not hex.
fn random_alnum(len: usize) -> String {
    const CHARS: &[u8] = b"0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    let mut out = String::with_capacity(len);
    for _ in 0..len {
        out.push(CHARS[rand::random::<usize>() % CHARS.len()] as char);
    }
    out
}

/// `cloudmusic_dll_encode_id` from the desktop client: XOR with the fixed key,
/// MD5 the UTF-8 bytes, then base64. Used for `register/anonimous`.
fn cloudmusic_dll_encode_id(device_id: &str) -> String {
    use base64::Engine as _;
    const KEY: &[u8] = b"3go8&$8*3*3h0k(2)2";
    let xored: Vec<u8> = device_id
        .bytes()
        .enumerate()
        .map(|(i, byte)| byte ^ KEY[i % KEY.len()])
        .collect();
    base64::engine::general_purpose::STANDARD.encode(crypto::md5_bytes(&xored))
}

/// A cookie header only identifies a session when it carries a non-empty
/// `MUSIC_U`; an anonymous `NMTID` must not be saved as a login.
fn has_login_token(cookie: &str) -> bool {
    cookie.split(';').any(|part| {
        part.trim()
            .strip_prefix("MUSIC_U=")
            .is_some_and(|value| !value.is_empty())
    })
}

/// QR steps are safe to repeat (a new unikey, or one more poll of the same
/// key). Both reference clients retry once after a network-level failure;
/// that single retry stops a transient connection reset from killing a scan.
fn qr_retryable(error: &CoreError) -> bool {
    match error {
        CoreError::Transport(_) => true,
        CoreError::Http { status, .. } => *status >= 500 || *status == 429,
        _ => false,
    }
}

impl qobject::SparkMusicClient {
    pub fn route_count(&self) -> i32 {
        Catalog::global().len() as i32
    }

    pub fn group_count(&self) -> i32 {
        Catalog::global().group_count() as i32
    }

    pub fn route_info(&self, route: &QString) -> QString {
        let spelling = route.to_string();
        match Catalog::global().get(&spelling) {
            Some(info) => qstring(serde_json::to_string(info).unwrap_or_default()),
            None => qstring(CoreError::UnknownRoute(spelling).to_json().to_string()),
        }
    }

    pub fn search_routes(&self, query: &QString, limit: i32) -> QString {
        let needle = query.to_string();
        let limit = limit.max(1) as usize;
        let routes: Vec<Value> = Catalog::global()
            .find(&needle, None)
            .into_iter()
            .take(limit)
            .filter_map(|info| serde_json::to_value(info).ok())
            .collect();
        qstring(Value::Array(routes).to_string())
    }

    pub fn call(&self, route: &QString, params_json: &QString) -> QString {
        let route = route.to_string();
        let result = self
            .transport
            .call(&route, &parse_params(&params_json.to_string()));
        self.persist_login_session(&route);
        result_json(result)
    }

    pub fn search_songs(&self, keyword: &QString, limit: i32, offset: i32) -> QString {
        let keyword = keyword.to_string();
        let mut params = Map::new();
        params.insert("s".into(), Value::String(keyword.clone()));
        params.insert("keyword".into(), Value::String(keyword.clone()));
        params.insert("type".into(), Value::from(1));
        params.insert("limit".into(), Value::from(limit.max(1)));
        params.insert("offset".into(), Value::from(offset.max(0)));
        params.insert("total".into(), Value::Bool(true));
        let result = self.transport.call("v1/search/get", &params);
        if result.is_ok() {
            let _ = self.db.record_search(&keyword);
        }
        result_json(result)
    }

    pub fn song_detail(&self, id: i64) -> QString {
        let mut params = Map::new();
        params.insert("id".into(), Value::from(id));
        params.insert("c".into(), Value::String(format!("[{{\"id\":{id}}}]")));
        params.insert("v".into(), Value::from(1));
        params.insert("rv".into(), Value::from(1));
        params.insert("level".into(), Value::String("exhigh".into()));
        result_json(self.transport.call("v3/song/detail", &params))
    }

    pub fn song_url(&self, ids: &QString, level: &QString) -> QString {
        let mut params = Map::new();
        params.insert("ids".into(), Value::String(ids_json(&ids.to_string())));
        let level = level.to_string();
        params.insert(
            "level".into(),
            Value::String(if level.is_empty() {
                "exhigh".into()
            } else {
                level
            }),
        );
        params.insert("encodeType".into(), Value::String("flac".into()));
        result_json(self.transport.call("song/enhance/player/url/v1", &params))
    }

    pub fn lyric(&self, id: i64) -> QString {
        let key = format!("lyric:{id}");
        if let Some(cached) = self.db.cache_get(&key, 7 * 24 * 3600) {
            return qstring(cached);
        }
        let mut params = Map::new();
        params.insert("id".into(), Value::from(id));
        params.insert("cp".into(), Value::Bool(false));
        params.insert("lv".into(), Value::from(-1));
        params.insert("tv".into(), Value::from(-1));
        params.insert("rv".into(), Value::from(-1));
        params.insert("kv".into(), Value::from(-1));
        let result = self.transport.call("song/lyric/v1", &params);
        if let Ok(value) = &result {
            let _ = self.db.cache_put(&key, &value.to_string());
        }
        result_json(result)
    }

    pub fn playlist(&self, id: i64, limit: i32) -> QString {
        // NetEase caps a detail window at 1000; never ask for more.
        let limit = limit.clamp(1, 1000);
        // Cache per login session: 「我喜欢的音乐」 has a different meaning for
        // every account and an anonymous answer is often empty.
        let session = self.transport.session_key();
        let key = format!("playlist:{session}:{id}:{limit}");
        if let Some(cached) = self.db.cache_get(&key, 6 * 3600) {
            if let Ok(value) = serde_json::from_str::<Value>(&cached) {
                if playlist_cacheable(&value) {
                    return qstring(cached);
                }
            }
        }

        let mut params = Map::new();
        params.insert("id".into(), Value::from(id));
        params.insert("n".into(), Value::from(limit));
        params.insert("s".into(), Value::from(0));
        params.insert("v".into(), Value::from(1));
        let mut result = self.transport.call("v6/playlist/detail", &params);

        if let Ok(value) = &mut result {
            if is_code_ok(value) {
                self.hydrate_playlist(value, limit);
            }
        }

        // Risk control occasionally rejects one envelope while the other
        // works; retry the same request once through weapi. An empty eapi
        // answer (no tracks and no track ids) is worth one retry too.
        let usable = result
            .as_ref()
            .map(|value| {
                is_code_ok(value)
                    && (track_count(value) > 0 || !playlist_track_ids(value).is_empty())
            })
            .unwrap_or(false);
        if !usable {
            if let Ok(mut value) = self
                .transport
                .call_mode("v6/playlist/detail", &params, "weapi")
            {
                if is_code_ok(&value) {
                    self.hydrate_playlist(&mut value, limit);
                    result = Ok(value);
                }
            }
        }

        if let Ok(value) = &result {
            if playlist_cacheable(value) {
                let _ = self.db.cache_put(&key, &value.to_string());
            }
        }
        result_json(result)
    }

    /// v6 returns every liked-song id in `playlist.trackIds` but only a small
    /// `tracks` window (often empty for `specialType == 5`). Resolve the
    /// requested window through `song/detail` before handing it to QML.
    fn hydrate_playlist(&self, value: &mut Value, limit: i32) {
        let track_ids = playlist_track_ids(value);
        if track_ids.is_empty() {
            return;
        }
        let have = value
            .pointer("/playlist/tracks")
            .and_then(Value::as_array)
            .map(Vec::len)
            .unwrap_or(0);
        let want = (limit.clamp(1, 1000) as usize).min(track_ids.len());
        if have >= want {
            return;
        }

        // A liked playlist can expose 800+ trackIds; `song/detail` is happier
        // with bounded batches, and the result is concatenated in reading order.
        let mut songs: Vec<Value> = Vec::with_capacity(want);
        for chunk in track_ids[..want].chunks(200) {
            let ids = chunk
                .iter()
                .map(|id| id.to_string())
                .collect::<Vec<_>>()
                .join(",");
            let c = chunk
                .iter()
                .map(|id| format!("{{\"id\":{id}}}"))
                .collect::<Vec<_>>()
                .join(",");
            let mut params = Map::new();
            params.insert("ids".into(), Value::String(format!("[{ids}]")));
            params.insert("c".into(), Value::String(format!("[{c}]")));
            if let Ok(response) = self.transport.call("v3/song/detail", &params) {
                if let Some(batch) = response.get("songs").and_then(Value::as_array) {
                    songs.extend(batch.iter().cloned());
                }
            }
        }
        if !songs.is_empty() {
            if let Some(playlist) = value.get_mut("playlist").and_then(Value::as_object_mut) {
                playlist.insert("tracks".into(), Value::Array(songs));
            }
        }
    }

    pub fn album(&self, id: i64) -> QString {
        let route = format!("album/{id}");
        result_json(self.transport.call(&route, &Map::new()))
    }

    pub fn artist(&self, id: i64) -> QString {
        let mut params = Map::new();
        params.insert("artistId".into(), Value::from(id));
        result_json(self.transport.call("artist/detail/dynamic/v2", &params))
    }

    pub fn song_comments(&self, id: i64, limit: i32, offset: i32) -> QString {
        let mut params = Map::new();
        params.insert("threadId".into(), Value::String(format!("R_SO_4_{id}")));
        params.insert("resourceId".into(), Value::from(id));
        params.insert("resourceType".into(), Value::from(4));
        params.insert("limit".into(), Value::from(limit.max(1)));
        params.insert("offset".into(), Value::from(offset.max(0)));
        result_json(self.transport.call("v1/resource/comments", &params))
    }

    pub fn mode(&self) -> QString {
        qstring(self.transport.mode())
    }

    pub fn set_mode(&self, mode: &QString) {
        let mode = mode.to_string();
        if ["eapi", "weapi", "api", "linuxapi"].contains(&mode.as_str()) {
            self.transport.set_mode(&mode);
        }
    }

    pub fn set_cookie(&self, cookie: &QString) {
        self.transport.set_cookie_header(&cookie.to_string());
        self.persist_session();
    }

    pub fn clear_cookies(&self) {
        self.transport.clear_cookies();
        *self.anonymous_tried.write().expect("anonymous lock") = false;
    }

    pub fn cookie_header(&self) -> QString {
        qstring(self.transport.current_cookie_header())
    }

    pub fn app_version(&self) -> QString {
        qstring(APP_VERSION)
    }

    /// 803 (and password login) can return the session cookie in a `cookie`
    /// field in addition to Set-Cookie headers; merge whichever is present.
    fn absorb_login(&self, value: &Value) {
        if let Some(cookie) = value.get("cookie").and_then(Value::as_str) {
            if !cookie.is_empty() {
                self.transport.set_cookie_header(cookie);
            }
        }
        self.persist_session();
    }

    /// Store the live jar when it carries a non-empty login token.
    fn persist_session(&self) {
        let cookie = self.transport.current_cookie_header();
        if has_login_token(&cookie) {
            let _ = self.db.save_session(&cookie);
        }
    }

    /// Generic `call`/`callWithMode` paths (the SMS form uses the latter) need
    /// the same persistence as the typed login wrappers, otherwise the app is
    /// signed in for one run and anonymous after a restart.
    fn persist_login_session(&self, route: &str) {
        let canonical = crate::catalog::canonical(route);
        if canonical == "login"
            || canonical.starts_with("login/")
            || canonical.starts_with("register/")
        {
            self.persist_session();
        }
    }

    /// Call one QR step, retrying once after a transport/5xx failure.
    fn call_qr(&self, route: &str, params: &Map<String, Value>, mode: &str) -> CoreResult<Value> {
        match self.transport.call_mode(route, params, mode) {
            Ok(value) => Ok(value),
            Err(error) if qr_retryable(&error) => {
                std::thread::sleep(std::time::Duration::from_millis(300));
                self.transport.call_mode(route, params, mode)
            }
            Err(error) => Err(error),
        }
    }

    // ------------------------------------------------------------------ login
    /// API-enhanced/folia send an anonymous MUSIC_A identity with the QR
    /// requests; the webplayer has one too. `register/anonimous` works through
    /// the plain api envelope with the desktop client's encoded device id.
    /// Failure is non-fatal: the QR flow can still work anonymously.
    fn ensure_anonymous_identity(&self) {
        let cookie = self.transport.current_cookie_header();
        if has_login_token(&cookie)
            || cookie
                .split(';')
                .any(|part| part.trim().starts_with("MUSIC_A="))
        {
            return;
        }
        let mut tried = self.anonymous_tried.write().expect("anonymous lock");
        if *tried {
            return;
        }
        *tried = true;
        drop(tried);

        let device_id = self.transport.device_id().to_string();
        use base64::Engine as _;
        let encoded_id = cloudmusic_dll_encode_id(&device_id);
        let username = base64::engine::general_purpose::STANDARD
            .encode(format!("{device_id} {encoded_id}").as_bytes());
        let mut params = Map::new();
        params.insert("username".into(), Value::String(username));
        if let Ok(value) = self.call_qr("register/anonimous", &params, "api") {
            if value.get("code").and_then(Value::as_i64) == Some(200) {
                // The API-enhanced cookie preprocessing adds these on every
                // request; keep the same web identity alongside MUSIC_A/NMTID.
                let seed = format!(
                    "os=pc; appver=3.1.17.204416;                      osver=Microsoft-Windows-10-Professional-build-19045-64bit;                      channel=netease; deviceId={device_id};                      __remember_me=true; ntes_kaola_ad=1; WEVNSM=1.0.0"
                );
                self.transport.set_cookie_header(&seed);
            }
        }
    }

    // The encrypted body must contain exactly the parameters the endpoint
    // expects. Extra fields (e.g. a timestamp) make NetEase answer 8821
    // instead of 801, which looks like a broken QR code.
    pub fn login_qr_key(&self) -> QString {
        self.ensure_anonymous_identity();
        // Mirror https://music.163.com/st/webplayer: its login page calls the
        // plain `/api/login/qrcode/unikey` route with type 3 on Windows/Linux
        // (4 on macOS). The old eapi/weapi type-1 combination is what gets
        // answered with 8821 after confirmation.
        let qr_type = if cfg!(target_os = "macos") { 4 } else { 3 };
        let mut params = Map::new();
        params.insert("type".into(), Value::from(qr_type));

        for mode in ["api", "weapi", "eapi"] {
            if let Ok(value) = self.call_qr("login/qrcode/unikey", &params, mode) {
                if value.get("unikey").is_some() {
                    *self.qr_mode.write().expect("qr mode lock") = mode.to_string();
                    *self.qr_type.write().expect("qr type lock") = qr_type;
                    return result_json(Ok(value));
                }
            }
        }
        result_json(Err(CoreError::Transport(
            "no unikey from api/weapi/eapi".to_string(),
        )))
    }

    pub fn login_qr_check(&self, key: &QString) -> QString {
        let qr_type = *self.qr_type.read().expect("qr type lock");
        let mut params = Map::new();
        params.insert("key".into(), Value::String(key.to_string()));
        params.insert("type".into(), Value::from(qr_type));

        let mode = self.qr_mode.read().expect("qr mode lock").clone();
        let result = self.call_qr("login/qrcode/client/login", &params, &mode);
        if let Ok(value) = &result {
            self.absorb_login(value);
        }
        result_json(result)
    }

    pub fn login_cellphone(&self, phone: &QString, password: &QString) -> QString {
        let mut params = Map::new();
        params.insert("phone".into(), Value::String(phone.to_string()));
        params.insert("countrycode".into(), Value::String("86".into()));
        params.insert(
            "md5_password".into(),
            Value::String(crypto::md5_hex(password.to_string().as_bytes())),
        );
        params.insert("rememberLogin".into(), Value::String("true".into()));
        let result = self
            .transport
            .call_mode("login/cellphone", &params, "weapi");
        if let Ok(value) = &result {
            self.absorb_login(value);
        }
        result_json(result)
    }

    pub fn send_sms_code(&self, phone: &QString) -> QString {
        let mut params = Map::new();
        params.insert("cellphone".into(), Value::String(phone.to_string()));
        params.insert("ctcode".into(), Value::String("86".into()));
        result_json(
            self.transport
                .call_mode("sms/captcha/sent", &params, "weapi"),
        )
    }

    pub fn login_email(&self, user: &QString, password: &QString) -> QString {
        let mut params = Map::new();
        params.insert("email".into(), Value::String(user.to_string()));
        params.insert(
            "md5_password".into(),
            Value::String(crypto::md5_hex(password.to_string().as_bytes())),
        );
        params.insert("rememberLogin".into(), Value::String("true".into()));
        let result = self.transport.call_mode("login", &params, "weapi");
        if let Ok(value) = &result {
            self.absorb_login(value);
        }
        result_json(result)
    }

    pub fn account(&self) -> QString {
        result_json(
            self.transport
                .call_mode("nuser/account/get", &Map::new(), "api"),
        )
    }

    pub fn user_playlists(&self, uid: i64) -> QString {
        let mut params = Map::new();
        params.insert("uid".into(), Value::from(uid));
        params.insert("limit".into(), Value::from(1000));
        params.insert("offset".into(), Value::from(0));
        params.insert("includeVideo".into(), Value::Bool(true));
        params.insert("newStyle".into(), Value::Bool(true));
        let mut result = self.transport.call("user/playlist", &params);
        if !result.as_ref().map(is_code_ok).unwrap_or(false) {
            if let Ok(fallback) = self.transport.call_mode("user/playlist", &params, "weapi") {
                if is_code_ok(&fallback) || result.is_err() {
                    result = Ok(fallback);
                }
            }
        }
        result_json(result)
    }

    pub fn call_with_mode(
        &self,
        route: &QString,
        params_json: &QString,
        mode: &QString,
    ) -> QString {
        let route = route.to_string();
        let result = self.transport.call_mode(
            &route,
            &parse_params(&params_json.to_string()),
            &mode.to_string(),
        );
        self.persist_login_session(&route);
        result_json(result)
    }

    pub fn favorites(&self) -> QString {
        let items: Vec<Value> = self
            .db
            .favorites()
            .unwrap_or_default()
            .into_iter()
            .map(Track::into_json)
            .collect();
        qstring(Value::Array(items).to_string())
    }

    pub fn add_favorite(&self, track_json: &QString) -> bool {
        match serde_json::from_str::<Track>(&track_json.to_string()) {
            Ok(track) => self.db.add_favorite(&track).is_ok(),
            Err(_) => false,
        }
    }

    pub fn remove_favorite(&self, song_id: i64) -> bool {
        self.db.remove_favorite(song_id).is_ok()
    }

    pub fn is_favorite(&self, song_id: i64) -> bool {
        self.db.is_favorite(song_id).unwrap_or(false)
    }

    pub fn record_play(&self, track_json: &QString) {
        if let Ok(track) = serde_json::from_str::<Track>(&track_json.to_string()) {
            let _ = self.db.record_play(&track);
        }
    }

    pub fn history(&self, limit: i32) -> QString {
        let items: Vec<Value> = self
            .db
            .history(limit.max(1) as i64)
            .unwrap_or_default()
            .into_iter()
            .map(Track::into_json)
            .collect();
        qstring(Value::Array(items).to_string())
    }

    pub fn clear_history(&self) {
        let _ = self.db.clear_history();
    }

    pub fn setting(&self, key: &QString) -> QString {
        qstring(self.db.setting(&key.to_string()).unwrap_or_default())
    }

    pub fn set_setting(&self, key: &QString, value: &QString) {
        let _ = self.db.set_setting(&key.to_string(), &value.to_string());
    }

    pub fn save_session(&self) -> bool {
        let cookie = self.transport.current_cookie_header();
        if !has_login_token(&cookie) {
            return false;
        }
        self.db.save_session(&cookie).is_ok()
    }

    pub fn load_session(&self) -> QString {
        match self.db.load_session() {
            Some(cookie) => {
                self.transport.set_cookie_header(&cookie);
                qstring(cookie)
            }
            None => qstring(""),
        }
    }

    pub fn clear_session(&self) {
        let _ = self.db.clear_session();
    }

    pub fn search_history(&self, limit: i32) -> QString {
        let items: Vec<String> = self
            .db
            .search_history(limit.max(1) as i64)
            .unwrap_or_default();
        qstring(serde_json::to_string(&items).unwrap_or_else(|_| "[]".into()))
    }

    pub fn clear_search_history(&self) {
        let _ = self.db.clear_search_history();
    }

    pub fn cache_stats(&self) -> QString {
        let (entries, bytes) = self.db.cache_stats();
        qstring(format!("{{\"entries\":{entries},\"bytes\":{bytes}}}"))
    }

    pub fn clear_cache(&self) {
        let _ = self.db.clear_cache();
    }

    /// Export favourites as an extended M3U8 playlist.
    ///
    /// Entries point at the public song page rather than a stream URL: the
    /// CDN links expire within minutes, the page link stays valid.
    pub fn export_favorites(&self, path: &QString) -> QString {
        let favorites = self.db.favorites().unwrap_or_default();
        if favorites.is_empty() {
            return qstring("");
        }
        let mut m3u8 = String::from("#EXTM3U\n");
        for track in &favorites {
            m3u8.push_str(&format!(
                "#EXTINF:{},{} - {}\nhttps://music.163.com/song?id={}\n",
                track.duration.max(0),
                if track.artist.is_empty() {
                    "Unknown"
                } else {
                    &track.artist
                },
                track.title,
                track.id
            ));
        }

        let requested = path.to_string();
        let candidates: Vec<std::path::PathBuf> = if requested.trim().is_empty() {
            default_export_candidates()
        } else {
            vec![std::path::PathBuf::from(requested.trim())]
        };

        for target in candidates {
            if let Some(parent) = target.parent() {
                let _ = std::fs::create_dir_all(parent);
            }
            if std::fs::write(&target, m3u8.as_bytes()).is_ok() {
                return qstring(target.to_string_lossy());
            }
        }
        qstring("")
    }

    pub fn qr_matrix(&self, text: &QString) -> QString {
        // High error correction: the design overlays a seal on the matrix, so
        // the code must tolerate damaged modules.
        match qrcode::QrCode::with_error_correction_level(
            text.to_string().as_bytes(),
            qrcode::EcLevel::H,
        ) {
            Ok(code) => {
                let width = code.width();
                let colors = code.to_colors();
                let mut out = String::with_capacity((width + 1) * width);
                for y in 0..width {
                    for x in 0..width {
                        out.push(if colors[y * width + x] == qrcode::Color::Dark {
                            '1'
                        } else {
                            '0'
                        });
                    }
                    if y + 1 < width {
                        out.push('\n');
                    }
                }
                qstring(out)
            }
            Err(_) => qstring(""),
        }
    }
}

/// Convenience for Rust callers and tests: catalog stats as JSON.
pub fn catalog_summary() -> Value {
    json!({
        "routes": Catalog::global().len(),
        "groups": Catalog::global().group_count(),
        "app_version": APP_VERSION,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ids_are_json_arrays() {
        assert_eq!(ids_json("347230"), "[347230]");
        assert_eq!(ids_json("347230, 347231"), "[347230,347231]");
        assert_eq!(ids_json("abc"), "[\"abc\"]");
    }

    #[test]
    fn params_parse_only_objects() {
        assert!(parse_params("not json").is_empty());
        assert!(parse_params("[1,2]").is_empty());
        assert_eq!(parse_params(r#"{"a":1}"#).len(), 1);
    }

    #[test]
    fn catalog_summary_has_the_expected_shape() {
        let summary = catalog_summary();
        assert_eq!(summary["routes"], 1293);
        assert_eq!(summary["groups"], 150);
    }

    #[test]
    fn playlist_track_ids_accept_objects_and_scalars() {
        let value = json!({
            "playlist": {
                "trackIds": [
                    {"id": 1, "v": 0},
                    {"id": 2},
                    3,
                    "4"
                ]
            }
        });
        assert_eq!(playlist_track_ids(&value), vec![1, 2, 3, 4]);
        assert!(playlist_track_ids(&json!({"playlist": {}})).is_empty());
    }

    #[test]
    fn empty_or_failed_playlists_are_not_cached() {
        let empty = json!({"code": 200, "playlist": {"tracks": []}});
        assert!(!playlist_cacheable(&empty));
        let denied = json!({"code": 301, "playlist": {"tracks": [{"id": 1}]}});
        assert!(!playlist_cacheable(&denied));
        let good = json!({"code": 200, "playlist": {
            "tracks": [{"id": 1, "name": "x"}]
        }});
        assert!(playlist_cacheable(&good));
    }

    #[test]
    fn anonymous_username_matches_the_desktop_encoding() {
        let device = "0123456789abcdef0123456789abcdef";
        assert_eq!(cloudmusic_dll_encode_id(device), "l5/rc1nh0Qv3B2jfKxnZiQ==");
        use base64::Engine as _;
        let username = base64::engine::general_purpose::STANDARD
            .encode(format!("{device} {}", cloudmusic_dll_encode_id(device)));
        assert_eq!(
            username,
            "MDEyMzQ1Njc4OWFiY2RlZjAxMjM0NTY3ODlhYmNkZWYgbDUvcmMxbmgwUXYzQjJqZkt4blppUT09"
        );
    }

    #[test]
    fn only_transport_and_server_failures_are_retried_for_qr() {
        assert!(qr_retryable(&CoreError::Transport("reset".into())));
        assert!(qr_retryable(&CoreError::Http {
            status: 502,
            body: String::new()
        }));
        assert!(qr_retryable(&CoreError::Http {
            status: 429,
            body: String::new()
        }));
        assert!(!qr_retryable(&CoreError::Http {
            status: 400,
            body: String::new()
        }));
        assert!(!qr_retryable(&CoreError::BadRequest("x".into())));
    }

    #[test]
    fn only_a_non_empty_music_u_counts_as_a_login() {
        assert!(has_login_token("MUSIC_U=abc; __csrf=tok"));
        assert!(has_login_token("__csrf=tok; MUSIC_U=abc"));
        assert!(!has_login_token("NMTID=abc"));
        assert!(!has_login_token("MUSIC_U=; __csrf=tok"));
        assert!(!has_login_token(""));
    }

    #[test]
    fn success_codes_are_strict_but_missing_code_is_ok() {
        assert!(is_code_ok(&json!({"code": 200})));
        assert!(!is_code_ok(&json!({"code": 301})));
        assert!(is_code_ok(&json!({"playlist": {}})));
    }
}
